var BNC=[['#0f6b44','#06251a'],['#1b8f6a','#0a3b4d'],['#5b4bff','#12104a'],['#e8582a','#4a1230'],['#0f8fd8','#0b2a4d'],['#c43b8a','#2a1252'],['#f0a000','#4a2a00'],['#9be7ff','#7c5cff']];
