/* ---- scales ---- */
var EF=[[65,85,'EF0'],[86,110,'EF1'],[111,135,'EF2'],[136,165,'EF3'],[166,200,'EF4'],[201,260,'EF5']],FF=[[40,72,'F0'],[73,112,'F1'],[113,157,'F2'],[158,206,'F3'],[207,260,'F4'],[261,318,'F5']];
function ssCat(w){return w<39?'Tropical depression':w<74?'Tropical storm':w<96?'Category 1':w<111?'Category 2':w<130?'Category 3':w<157?'Category 4':'Category 5'}
stnReg({id:'scale',pack:'met',topic:'torn',notes:'n-torn',title:'Scale it',sub:'EF, F or Saffir-Simpson',ic:'<path d="M4 20V10M10 20V6M16 20V13M22 20V3"/>',
 task:function(s){return s.hur?'A hurricane is reported with <b>'+s.w+' mph</b> sustained winds. Rate it.':'A tornado hit on <b>'+s.date+'</b>. A survey estimates a <b>'+s.w+' mph</b> peak gust from the damage. Rate it.'},
 gen:function(){if(Math.random()<.4){var w=SI(30,185);return {hur:1,w:w}}var yr=SP([1974,1991,1999,2003,2006,2007,2011,2013,2019,2024]),mo=SP(['April','May','June','October']),pre=yr<2007,tab=pre?FF:EF,t=SP(tab);return {hur:0,pre:pre,w:SI(t[0],t[1]),date:mo+' '+SI(1,28)+', '+yr,yr:yr}},
 view:function(s){return s.hur?msel(s,'cat','Rating',['Tropical depression','Tropical storm','Category 1','Category 2','Category 3','Category 4','Category 5'])+msel(s,'maj','Is it a major hurricane?',['Yes','No']):msel(s,'sc','Which scale applies?',[['F','Fujita (F) scale'],['EF','Enhanced Fujita (EF) scale']])+msel(s,'r','Rating',['0','1','2','3','4','5'].map(function(x){return [x,'Rating '+x]}))},
 act:function(s,a,v){s.in[a]=v;return false},
 check:function(s){var a=s.in,L=[],sc=0;if(s.hur){var cat=ssCat(s.w),maj=s.w>=111?'Yes':'No';var o1=a.cat===cat,o2=a.maj===maj;if(o1)sc+=.7;if(o2)sc+=.3;L.push([o1,cat+' for '+s.w+' mph sustained wind.']);L.push([o2,maj==='Yes'?'Category 3 or higher is a major hurricane.':'Not a major hurricane (needs Category 3, 111 mph or more).']);
  return {score:sc,lines:L,steps:['Saffir-Simpson uses <b>sustained wind</b>. Under 39 mph: depression. 39–73 mph: tropical storm. 74+ mph: hurricane.','Cat 1: 74–95 · Cat 2: 96–110 · Cat 3: 111–129 (major) · Cat 4: 130–156 (major) · Cat 5: 157+ (major).',s.w+' mph falls in <b>'+cat+'</b>.','The scale rates wind only. Storm surge is often the deadliest hazard, so it is not captured by the category.']}}
  var sc0=s.pre?'F':'EF',tab=s.pre?FF:EF,r=tab.filter(function(t){return s.w>=t[0]&&s.w<=t[1]})[0][2].replace('EF','').replace('F','');var o1=a.sc===sc0,o2=a.r===r;if(o1)sc+=.5;if(o2)sc+=.5;L.push([o1,'Use '+(sc0==='F'?'the original F scale (before 1 Feb 2007).':'the EF scale (on or after 1 Feb 2007).')]);L.push([o2,s.w+' mph → '+sc0+r+'.']);
  return {score:sc,lines:L,steps:['Check the <b>date first</b>: the F scale was used before 1 February 2007; the EF scale is used on or after that date.','Both scales rate <b>damage</b>, not measured wind. The wind speed is an estimate tied to the damage.','EF scale (3-second gust): EF0 65–85 · EF1 86–110 · EF2 111–135 · EF3 136–165 · EF4 166–200 · EF5 over 200 mph.','Original F scale estimates: F0 40–72 · F1 73–112 · F2 113–157 · F3 158–206 · F4 207–260 · F5 261–318 mph.',s.w+' mph on '+s.date+' → <b>'+sc0+r+'</b>.']}},
 mats:'the EF and Saffir-Simpson tables from your notes, tornado and hurricane reports from spc.noaa.gov and nhc.noaa.gov.',
 real:['Open SPC’s storm reports page for a past day and pick 3 tornado reports. Write the date, location and rating.','For each, say which scale applies from the date alone, then find the matching wind range.','Open an NHC advisory archive for an Atlantic hurricane. Rate the storm at three different advisories from the sustained winds.','Quiz a friend with a random wind speed and a random date every day.']});

