/* ---- radar ---- */
var RSIG=[['hook','Hook echo'],['tvs','TVS (tornado vortex signature)'],['debris','Debris ball'],['bow','Bow echo'],['fine','Fine line']],
 RHZ=[['tor','Tornado'],['wind','Damaging straight-line wind'],['gf','Gust front: wind shift and new storms'],['flood','Flash flooding']],
 RPR=[['tw','Tornado Warning'],['svr','Severe Thunderstorm Warning'],['ffw','Flash Flood Warning'],['none','No warning by itself; watch for new storms']],
 RANS={hook:['hook','tor','tw'],tvs:['tvs','tor','tw'],debris:['debris','tor','tw'],bow:['bow','wind','svr'],fine:['fine','gf','none']};
function rBlob(x,y,cx,cy,sx,sy,a){var dx=(x-cx)/sx,dy=(y-cy)/sy;return a*Math.exp(-(dx*dx+dy*dy)/2)}
function rField(k,x,y,i){ /* returns [dbz, vel, cc] */
 var d=0,v=0,cc=.985,rx=0-x,ry=150-y;
 function arc(cx,cy,r,a0,a1,n,w,amp){var m=0;for(var j=0;j<=n;j++){var an=a0+(a1-a0)*j/n;m=Math.max(m,rBlob(x,y,cx+r*Math.cos(an),cy+r*Math.sin(an),w,w,amp))}return m}
 var nz=(Math.sin(x*.9+y*.7)+Math.sin(x*.31-y*1.1))*.5;
 if(k==='hook'||k==='tvs'||k==='debris'){d=Math.max(rBlob(x,y,78,66,26,22,56),rBlob(x,y,60,52,20,16,40),arc(100,93,17,-1.9,1.4,10,7,i==='hook'?52:44));
  var cxv=104,cyv=96,ux=(cxv-0)/Math.hypot(cxv,cyv-150),uy=(cyv-150)/Math.hypot(cxv,cyv-150),px=-uy,py=ux,s=k==='hook'?11:k==='tvs'?5.5:6,amp=k==='hook'?18:k==='tvs'?44:40;
  v=rBlob(x,y,cxv+px*s,cyv+py*s,k==='hook'?16:7,k==='hook'?16:7,amp)-rBlob(x,y,cxv-px*s,cyv-py*s,k==='hook'?16:7,k==='hook'?16:7,amp)+rBlob(x,y,75,70,40,40,8);
  if(k==='tvs')d=Math.max(rBlob(x,y,78,66,28,24,50),arc(100,93,17,-1.6,.9,8,6,34));
  if(k==='debris')cc=.985-.5*rBlob(x,y,104,96,8,8,1)}
 if(k==='bow'){var best=0;for(var j=0;j<=14;j++){var an=-2.3+j/14*1.9,cx=40+75*Math.cos(an),cy=100+75*Math.sin(an)*1.1;best=Math.max(best,rBlob(x,y,cx+Math.sin(an+1.6)*10,cy,13,13,j>5&&j<9?58:46))}d=Math.max(best,rBlob(x,y,50,100,35,40,26));v=rBlob(x,y,95,70,24,20,34)+rBlob(x,y,95,110,20,16,28)-rBlob(x,y,40,100,22,34,12)}
 if(k==='fine'){var best2=0;for(var j2=0;j2<=18;j2++){var an2=-.4+j2/18*1.6,cx2=0+88*Math.cos(an2-.1),cy2=150-88*Math.sin(an2+.15);best2=Math.max(best2,rBlob(x,y,cx2,cy2,3.2,3.2,26))}d=best2;var sd=Math.hypot(x-0,y-150)-88;v=Math.max(-10,Math.min(10,-sd*1.4))*Math.exp(-sd*sd/220)}
 return [d+nz,v,cc+(Math.sin(x*1.7+y*1.3))*.006]}
function rColR(z){if(z<12)return [0,0,0,0];var t=[[12,[120,200,255]],[20,[80,170,90]],[30,[40,150,40]],[40,[250,240,50]],[48,[255,150,30]],[55,[230,40,40]],[62,[200,60,200]]],c=t[0][1];for(var i=0;i<t.length;i++)if(z>=t[i][0])c=t[i][1];return [c[0],c[1],c[2],255]}
function rColV(v){var a=Math.min(1,Math.abs(v)/40);if(Math.abs(v)<2)return [150,150,150,255];return v<0?[Math.round(60-40*a),Math.round(180+60*a),Math.round(80-30*a),255]:[Math.round(170+80*a),Math.round(60-40*a),Math.round(60-40*a),255]}
function rColC(c){return c>.95?[230,230,235,255]:c>.85?[250,220,90,255]:c>.7?[255,140,50,255]:c>.55?[130,80,200,255]:[40,60,200,255]}
function radarPaint(s){['rd0','rd1','rd2'].forEach(function(id,pi){var cv=$(id);if(!cv)return;var g=cv.getContext('2d'),im=g.createImageData(150,150);for(var y=0;y<150;y++)for(var x=0;x<150;x++){var f=rField(s.k,x,y,s.k),c=pi===0?rColR(f[0]):pi===1?(f[0]>8?rColV(f[1]):[0,0,0,0]):(f[0]>12?rColC(f[2]):[0,0,0,0]),o=(y*150+x)*4;im.data[o]=c[0];im.data[o+1]=c[1];im.data[o+2]=c[2];im.data[o+3]=c[3]}g.putImageData(im,0,0)})}
stnReg({id:'radar',pack:'met',topic:'torn',notes:'n-torn',title:'Radar signatures',sub:'Reflectivity, velocity, CC',ic:'<circle cx="12" cy="12" r="9"/><circle cx="12" cy="12" r="4"/><path d="M12 12l6-6"/>',
 task:function(){return 'The radar is at the lower-left corner of each panel. Identify the signature, the main hazard and the NWS product you would expect.'},
 gen:function(){return {k:SP(['hook','tvs','debris','bow','fine'])}},
 view:function(s){return '<div class="radar">'+[['rd0','Reflectivity'],['rd1','Velocity'],['rd2','Correlation coefficient']].map(function(p){return '<figure><canvas id="'+p[0]+'" width="150" height="150"></canvas><figcaption>'+p[1]+'</figcaption></figure>'}).join('')+'</div><div class="small mute">Velocity: green = toward the radar, red = away. In CC, rain is high (light gray) and debris is low (blue).</div>'+msel(s,'sig','Signature',RSIG)+msel(s,'hz','Main hazard',RHZ)+msel(s,'pr','NWS product',RPR)},
 after:function(s){radarPaint(s)},
 act:function(s,a,v){s.in[a]=v;return false},
 check:function(s){var A=RANS[s.k],a=s.in,nm=function(L,k){return L.filter(function(x){return x[0]===k})[0][1]},sc=0,L=[];[['sig',RSIG,0],['hz',RHZ,1],['pr',RPR,2]].forEach(function(r){var ok=a[r[0]]===A[r[2]];if(ok)sc+=1/3;L.push([ok,nm(r[1],A[r[2]])])});
  var why={hook:'The reflectivity panel shows rain wrapping around a rotating updraft: a curved <b>hook</b> on the right-rear flank. Velocity shows rotation but it is broad and weak here.',tvs:'Velocity shows a <b>tight inbound-outbound pair</b> (green right next to red). That is intense, small-scale rotation: a tornado vortex signature.',debris:'There is a hook and a tight velocity pair, and the CC panel has a <b>blue hole of low correlation</b> in the hook. Mixed shapes and sizes (debris) lowers CC: a tornado is lofting debris.',bow:'Reflectivity bends into a bow. Velocity shows a broad area of strong outbound (red) flow behind the arc: <b>damaging straight-line wind</b>. Small tornadoes can hide in it.',fine:'A thin, weak line of echo with a green/red wind shift across it is a <b>fine line</b>: an outflow boundary or gust front. It is not a warned storm by itself but storms often form on it.'};
  return {score:sc,lines:L,steps:['Read all three panels together. One panel can mislead.',why[s.k],'Match the hazard: rotation or debris means tornado; a bow means wind; a thin boundary means a wind shift and new storms.','Match the product: tornado signatures lead to a <b>Tornado Warning</b>; bow echoes lead to a <b>Severe Thunderstorm Warning</b>; a fine line alone needs no warning, but watch for new storms.','Remember: toward the radar is negative (green); away is positive (red). Think “red = run away”.']}},
 mats:'a computer or phone with radar.weather.gov or an archived radar case from the NWS, notebook.',
 real:['Open a past severe-weather day on an NWS radar archive (search “NWS radar archive” or the event’s case page).','Look at reflectivity first. Find the hook, bow or thin line. Then switch to velocity and find the strongest green-red pair.','If correlation coefficient is available, look for a low-CC patch inside the hook (a debris ball).','Compare with the warnings and storm reports (spc.noaa.gov) from that day. Did your read match what NWS issued?']});

/* ---- sounding and hodograph ---- */
var LVL=[1000,925,850,700,600,500,400,300,250,200],SND={
 storm:{T:[30,24,20,6,-3,-12,-25,-41,-50,-58],D:[22,21,16,-4,-14,-26,-38,-52,-62,-70],h:[[0,0],[8,6],[14,16],[22,28],[30,36]],ans:'storm',sfc:[30,22]},
 cap:{T:[32,27,29,13,3,-8,-22,-38,-48,-57],D:[22,19,10,-2,-12,-24,-36,-50,-60,-68],h:[[0,0],[7,5],[13,13],[19,22],[26,30]],ans:'cap',sfc:[32,22]},
 fog:{T:[8,12,6,-2,-9,-18,-31,-47,-56,-60],D:[7.5,9,-2,-10,-18,-28,-40,-55,-65,-72],h:[[0,0],[3,0],[5,1],[6,2],[8,3]],ans:'fog',sfc:[8,7.5]},
 flood:{T:[26,22,19,10,3,-6,-19,-35,-45,-55],D:[25,21,18,9,2,-7,-20,-36,-46,-56],h:[[0,0],[2,1],[3,1],[4,3],[5,3]],ans:'flood',sfc:[26,25]}};
function sndSvg(k){var d=SND[k],X=function(t,p){return 40+(t+60)*3.1+((1000-p)*0.12)},Y=function(p){return 10+Math.log(1000/p)/Math.log(5)*160},l=function(arr,col,dash){return '<polyline fill="none" stroke="'+col+'" stroke-width="2.6" '+(dash?'stroke-dasharray="6 3" ':'')+'points="'+arr.map(function(t,i){return X(t,LVL[i])+','+Y(LVL[i])}).join(' ')+'"/>'},g='';
 LVL.forEach(function(p){g+='<line x1="30" y1="'+Y(p)+'" x2="330" y2="'+Y(p)+'" stroke="currentColor" opacity=".15"/><text x="2" y="'+(Y(p)+4)+'" font-size="9" fill="currentColor" stroke="none">'+p+'</text>'});
 var hx=function(u){return 70+u*3.8},hy=function(v){return 70-v*1.6},hp=d.h.map(function(p){return hx(p[0])+','+hy(p[1])}).join(' ');
 return '<svg viewBox="0 0 330 185" class="itsvg" fill="none" stroke-linecap="round" stroke-linejoin="round">'+g+l(d.T,'#e0412f')+l(d.D,'#2f7be0',1)+'<text x="200" y="150" font-size="10" fill="#e0412f" stroke="none" font-weight="700">Temperature</text><text x="200" y="164" font-size="10" fill="#2f7be0" stroke="none" font-weight="700">Dew point (dashed)</text></svg>'+
 '<div class="small mute" style="margin-top:6px">Hodograph (wind at each height, ground to upper levels):</div><svg viewBox="0 0 150 80" class="itsvg" style="max-width:220px" fill="none"><path d="M10 70H140M70 4V76" stroke="currentColor" opacity=".25"/><polyline points="'+hp+'" stroke="var(--pri)" stroke-width="2.4"/>'+d.h.map(function(p,i){return '<circle cx="'+hx(p[0])+'" cy="'+hy(p[1])+'" r="'+(i?2.4:3.6)+'" fill="var(--pri)" stroke="none"/>'}).join('')+'</svg>'}
var SNDCON=[['storm','Strong storms likely (instability + shear)'],['cap','Storms likely capped for now'],['fog','Fog and low cloud, no deep convection'],['flood','Deep moisture: heavy rain and flooding risk']];
stnReg({id:'sounding',pack:'met',topic:'upper',notes:'n-upper',title:'Sounding and hodograph',sub:'Skew-T style reading',ic:'<path d="M5 3v18M5 7l12 4-9 3 12 6"/>',
 task:function(s){return 'Read the sounding: the surface is <b>'+SND[s.k].sfc[0]+' °C / '+SND[s.k].sfc[1]+' °C</b> (temperature / dew point). Answer the four questions.'},
 gen:function(){return {k:SP(Object.keys(SND))}},
 view:function(s){var lv=LVL.map(function(p){return [String(p),p+' mb']});var inv=[];for(var i=0;i<LVL.length-1;i++)inv.push([LVL[i]+'-'+LVL[i+1],'between '+LVL[i]+' and '+LVL[i+1]+' mb']);
  return sndSvg(s.k)+msel(s,'moist','Where are T and Td closest (most moist level)?',lv)+msel(s,'inv','Where does temperature increase with height (an inversion)?',[['none','No inversion']].concat(inv))+fld(s,'lcl','Estimated LCL (cloud base)','m','125 × (T − Td)')+msel(s,'con','Best conclusion',SNDCON)},
 act:function(s,a,v){s.in[a]=v;return false},
 check:function(s){var d=SND[s.k],a=s.in,sp=LVL.map(function(p,i){return d.T[i]-d.D[i]}),mi=sp.indexOf(Math.min.apply(null,sp)),inv='none';for(var i=0;i<LVL.length-1;i++)if(d.T[i+1]>d.T[i]){inv=LVL[i]+'-'+LVL[i+1];break}
  var lcl=125*(d.sfc[0]-d.sfc[1]),ok1=Math.abs(+a.moist-LVL[mi])<=0||a.moist===String(LVL[mi])||sp[LVL.indexOf(+a.moist)]<=Math.min.apply(null,sp)+1.01,ok2=a.inv===inv,ok3=near(pv(a.lcl),lcl,.12)||Math.abs(pv(a.lcl)-lcl)<=60,ok4=a.con===d.ans,sc=(ok1?.25:0)+(ok2?.25:0)+(ok3?.25:0)+(ok4?.25:0);
  var why={storm:'Large instability (temperature falls fast, dry air at 700 mb), strong moisture at the surface, and a long, clockwise-curving hodograph (strong veering shear) favor supercells.',cap:'Warm, moist air near the ground sits under a warm layer (the inversion), the “cap”. Storms stay suppressed until something lifts air through the cap or it weakens, then they can explode.',fog:'T and Td nearly touch right at the surface and the temperature rises just above it: a shallow stable layer. The hodograph is short, so there is little shear. Expect fog or low cloud, not storms.',flood:'T and Td stay close from the surface to 500 mb: the whole column is moist. The hodograph is short (weak shear), so storms are slow movers dumping heavy rain: a flooding setup.'};
  return {score:sc,lines:[[ok1,'Closest T and Td: '+LVL[mi]+' mb (spread '+sp[mi].toFixed(1)+' °C). Lines close together mean moist or cloudy.'],[ok2,inv==='none'?'No inversion: temperature falls with height at every level.':'Inversion between '+inv.replace('-',' and ')+' mb (temperature rises with height).'],[ok3,'LCL ≈ 125 × ('+d.sfc[0]+' − '+d.sfc[1]+') = '+Math.round(lcl)+' m.'],[ok4,SNDCON.filter(function(x){return x[0]===d.ans})[0][1]+'.']],steps:['<b>Temperature</b> is the solid line, <b>dew point</b> the dashed line. Close together means moist or cloudy; far apart means dry.','An <b>inversion</b> is a layer where temperature <b>rises</b> with height. It is very stable and acts as a “cap”.','<b>LCL</b> (m) ≈ 125 × (T − Td) using the surface values: 125 × '+(d.sfc[0]-d.sfc[1]).toFixed(1)+' = '+Math.round(lcl)+' m. A low LCL (low cloud base) raises tornado risk.','<b>Hodograph:</b> a long, curving path means strong shear; curving clockwise with height (veering) favors supercells. A short path means weak shear.',why[s.k]+' CAPE alone is not enough: you also need shear and a lift trigger.']}},
 mats:'an upper-air sounding from spc.noaa.gov (sounding analysis) or weather.uwyo.edu, colored pencils, a printed Skew-T blank.',
 real:['Open an observed sounding for a station near a recent storm day. Print it.','Trace temperature in red and dew point in blue. Mark where they nearly touch and any layer where temperature increases with height.','Compute the LCL from the surface values: 125 × (T − Td).','Sketch the hodograph from the wind at 1, 3, 6 km. Decide: strong or weak shear? Then look up what happened and see if you were right.']});

/* ---- case study ---- */
var CASES={hurr:{n:'Hurricane landfall',hz:'Storm surge and wind',act:'Evacuate inland if told; never ride out surge',cl:['Named tropical system over warm Gulf water','Eye and eyewall seen on radar','Sustained winds 115 mph at landfall','Water pushed 12 ft above normal along the coast','Pressure fell to 940 mb','Rainfall bands spawned brief tornadoes']},
 torn:{n:'Tornado outbreak',hz:'Tornadoes',act:'Go to the lowest floor, interior room, away from windows',cl:['Spring afternoon, warm sector with dew points above 65 °F','Multiple supercells with hook echoes','Strong veering wind shear','Dryline and cold front approaching','Several tornado warnings in six hours','Damage rated EF3 on the survey']},
 dere:{n:'Derecho',hz:'Widespread straight-line wind',act:'Shelter indoors away from windows and trees',cl:['Long bow echo racing across several states','Gusts of 90 mph over a path 400+ miles long','Damage in one direction, no rotation','Fast-moving line late in the day after a hot humid day','Millions without power','Gust front visible as a fine line ahead of the storms']},
 blzd:{n:'Blizzard',hz:'Heavy snow, strong wind, whiteout',act:'Stay home, avoid travel, keep emergency supplies',cl:['Winds of 40 mph with falling and blowing snow','Visibility under a quarter mile for three hours','Deep low pressure with a strong pressure gradient','Temperatures near 10 °F','Drifts of 5 feet','Roads closed across the region']},
 flod:{n:'Flash flood',hz:'Rapid flooding',act:'Turn around; do not drive through flooded roads',cl:['Training thunderstorms over the same area','Rain rates of 3 inches per hour','8 inches of rain in 6 hours','Small creek rose 10 feet in an hour','Slow storm motion and very high precipitable water','Urban streets and underpasses flooded']},
 heat:{n:'Heat wave',hz:'Extreme heat',act:'Stay cool and hydrated; check on neighbors; never leave anyone in a car',cl:['Upper-level ridge (heat dome) stalled overhead','Highs above 100 °F for five days','Heat index over 110 °F with high dew points','Overnight lows stayed near 85 °F','Heat advisory and excessive heat warning issued','Drought and dry soils amplified temperatures']}};
stnReg({id:'case',pack:'met',topic:'cases',notes:'n-cases',title:'Case study',sub:'Name the event',ic:'<path d="M5 3h14v18H5zM9 8h6M9 12h6M9 16h4"/>',
 task:function(){return 'Read the data packet. Name the event, pick the clues that fit it, then give the main hazard and the safety action.'},
 gen:function(){var ks=Object.keys(CASES),k=SP(ks),t=CASES[k].cl.slice().sort(function(){return Math.random()-.5}),others=[];ks.filter(function(x){return x!==k}).forEach(function(o){CASES[o].cl.slice().sort(function(){return Math.random()-.5}).slice(0,2).forEach(function(c){others.push(c)})});var dec=others.sort(function(){return Math.random()-.5}).slice(0,4);return {k:k,pack:t.slice(0,3),all:t.slice(3,6).map(function(c){return [c,1]}).concat(dec.map(function(c){return [c,0]})).sort(function(){return Math.random()-.5}),pick:{}}},
 view:function(s){var c=CASES[s.k];return '<div class="packet"><b>Data packet</b><ul>'+s.pack.map(function(x){return '<li>'+esc(x)+'</li>'}).join('')+'</ul></div>'+msel(s,'ty','Event type',Object.keys(CASES).map(function(k){return [k,CASES[k].n]}))+'<div class="small" style="margin:10px 0 4px"><b>Which of these clues fit the same event?</b> Select all that apply.</div><div class="chipsel">'+s.all.map(function(a,i){return '<button class="ch'+(s.pick[i]?' on':'')+'" data-a="pk" data-v="'+i+'">'+esc(a[0])+'</button>'}).join('')+'</div>'+msel(s,'hz','Main hazard',Object.keys(CASES).map(function(k){return [k,CASES[k].hz]}))+msel(s,'ac','Safety action',Object.keys(CASES).map(function(k){return [k,CASES[k].act]}))},
 act:function(s,a,v){if(a==='pk'){s.pick[v]=!s.pick[v];return true}s.in[a]=v;return false},
 check:function(s){var c=CASES[s.k],a=s.in,ok1=a.ty===s.k,hit=0,bad=0,tot=s.all.filter(function(x){return x[1]}).length;s.all.forEach(function(x,i){if(s.pick[i]){x[1]?hit++:bad++}});var cs=Math.max(0,(hit-bad)/tot),ok3=a.hz===s.k,ok4=a.ac===s.k,sc=(ok1?.3:0)+cs*.3+(ok3?.2:0)+(ok4?.2:0);
  return {score:sc,lines:[[ok1,'Event: '+c.n+'.'],[cs>=.75,'Clues: '+hit+' of '+tot+' right'+(bad?', '+bad+' that belong to other events':'')+'.'],[ok3,'Main hazard: '+c.hz+'.'],[ok4,'Action: '+c.act+'.']],steps:['<b>Case method:</b> 1) name the storm type, 2) list the clues, 3) apply the scale or signature, 4) check dates (EF cutoff 1 Feb 2007).','Look for the one or two clues that only one event produces: surge + eyewall → hurricane; hooks + veering shear → tornadoes; a long bow echo with no rotation → derecho; blowing snow with low visibility → blizzard; training storms + huge rain totals → flash flood; a stalled ridge + 100 °F → heat wave.','Clues that fit this event: '+c.cl.map(esc).join('; ')+'.','Use official sources in real events: weather.gov, spc.noaa.gov, nhc.noaa.gov. In a real warning, follow the instructions there, not this app.']}},
 mats:'your notes’ case-study table, a map, data from ncei.noaa.gov (Storm Events Database) or weather.gov event summaries.',
 real:['Pick a historic event from your notes (Galveston 1900, Xenia 1974, 2011 outbreak, Katrina, Great Flood 1993…).','Find its NWS or NCEI event summary. Copy 6 data lines, hiding the event name.','Hand them to a partner. They name the storm type, list three clues, the main hazard and the safety action.','Swap roles. Aim to be right in under two minutes per case.']});

